  "python": "def pilot_policy(trace):
    if not trace:
        return None
    action, label = trace[-1]
    if action.name == 'publisher/publish':
        target = action.params.get('target')
        if target in ('website', 'newsletter') and 'CONFIDENTIAL' in label.subset:
            raise PolicyViolation('CONFIDENTIAL label cannot be written to ' + target)
    return None"
